        x = 0;
        check_output(1'b1);

        @(posedge clk);
        #1;
        if (dut.state !== 2'b10) begin
            $display("Time %0t: Incorrect state transition in B for x=0. Got %b", $time, dut.state);
            errors = errors + 1;
        end

        // Test 4: In State B, test x=1 -> should stay B, z=0
        x = 1;
        check_output(1'b0);

        @(posedge clk);
        #1;
        if (dut.state !== 2'b10) begin
            $display("Time %0t: Incorrect state transition in B for x=1. Got %b", $time, dut.state);
            errors = errors + 1;
